// Full-screen background bitmaps (NerdMinerV2 style): labels and panels are
// baked into the image, the UI only paints values into the field rectangles.
// Images and layout are generated by tools/make_backgrounds.py.
#pragma once

#include <stdint.h>

#include "bg_layout.h"

// Only the resolutions a board can show are linked in (~380-900 KiB each).
// A board env can pick its set itself, e.g. -DBG_HAS_240x135=1.
#if defined(BG_HAS_240x135) || defined(BG_HAS_320x170) || defined(BG_HAS_320x240)
// chosen in platformio.ini
#elif defined(DISPLAY_M5UNIFIED)
#define BG_HAS_240x135 1  // StickC Plus/Plus2, Cardputer
#define BG_HAS_320x240 1  // Core, Core2, Tough, CoreS3
#elif defined(DISPLAY_LGFX_T_DISPLAY)
#define BG_HAS_240x135 1
#elif defined(DISPLAY_LGFX_T_DISPLAY_S3)
#define BG_HAS_320x170 1
#elif defined(DISPLAY_LGFX_CYD)
#define BG_HAS_320x240 1
#endif

#ifndef BG_HAS_240x135
#define BG_HAS_240x135 0
#endif
#ifndef BG_HAS_320x170
#define BG_HAS_320x170 0
#endif
#ifndef BG_HAS_320x240
#define BG_HAS_320x240 0
#endif

namespace bg {

struct Rect {
    uint16_t x, y, w, h;
};

struct Set {
    uint16_t width, height;
    const uint16_t *pixels[SCREEN_COUNT];  // RGB565, row-major
    const Rect *rects;                     // indexed by Field
};

// Background set matching the panel size, or nullptr (procedural UI is used).
const Set *find(int width, int height);

}  // namespace bg
